<script lang="ts">
  import { session } from '../auth/session';
  import type { Work } from './api';
  let { work }: { work:Work }=$props();
  let lists=$state<{id:string;name:string}[]>([]);let listId=$state('');let listName=$state('À regarder');let error=$state('');let message=$state('');let busy=$state(false);let title=$state('');let plot=$state('');let year=$state<number|undefined>();let genres=$state('');let ids=$state('{}');let age=$state<number|undefined>();let copyId=$state('');
  $effect(()=>{title=work.title;plot=work.plot??work.description;year=work.year??undefined;genres=(work.genres??[]).join(', ');ids=JSON.stringify(work.externalIds??{},null,2);age=work.minimumAge??undefined;});
  async function loadLists(){try{const response=await fetch('/api/v1/lists');if(!response.ok)throw new Error('Listes indisponibles.');lists=(await response.json()).lists;listId=lists[0]?.id??'';}catch(cause){error=cause instanceof Error?cause.message:'Listes indisponibles.';}}
  async function mutate(path:string,method:string,body?:unknown,contentType='application/json'){
    busy=true;error='';message='';try{const response=await fetch(path,{method,headers:{'content-type':contentType,'x-csrf-token':$session?.csrfToken??''},body:body instanceof File?body:body===undefined?undefined:JSON.stringify(body)});if(!response.ok)throw new Error(`Enregistrement impossible (HTTP ${response.status}).`);message='Enregistré.';return response.status===204?true:await response.json();}catch(cause){error=cause instanceof Error?cause.message:'Enregistrement impossible.';return false;}finally{busy=false;}}
  async function save(event:SubmitEvent){event.preventDefault();let externalIds;try{externalIds=JSON.parse(ids);}catch{error='Les identifiants doivent être un objet JSON.';return;}if(await mutate(`/api/v1/admin/works/${work.id}/metadata`,'PUT',{title,plot,year:year??null,genres:genres.split(',').map(s=>s.trim()).filter(Boolean),externalIds,minimumAge:age??null}))window.location.reload();}
  async function create(){const result=await mutate('/api/v1/lists','POST',{name:listName});if(result){await loadLists();listId=result.id;}}
  async function upload(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(file&&await mutate(`/api/v1/works/${work.id}/poster`,'PUT',file,file.type))window.location.reload();}
</script>
<details ontoggle={event=>{if(event.currentTarget.open)void loadLists();}}><summary>Listes et gestion du média</summary>
<fieldset disabled={busy}><legend>Mes listes</legend><label>Liste<select bind:value={listId}><option value="">Choisir une liste</option>{#each lists as list(list.id)}<option value={list.id}>{list.name}</option>{/each}</select></label><button disabled={!listId} onclick={()=>mutate(`/api/v1/lists/${listId}/items/${work.id}`,'PUT')}>Ajouter à la liste</button><label>Nouvelle liste<input bind:value={listName} maxlength="100" /></label><button onclick={create}>Créer une liste</button></fieldset>
{#if $session?.user.role==='administrator'}<form onsubmit={save}><fieldset disabled={busy}><legend>Identification et métadonnées</legend><p>Identifiant de cette copie : <code>{work.id}</code></p>{#if work.globalMediaId}<p>Identité globale : <code>{work.globalMediaId}</code></p>{/if}<label>Titre<input required maxlength="512" bind:value={title} /></label><label>Année<input type="number" min="1800" max="2200" bind:value={year} /></label><label>Description<textarea bind:value={plot} maxlength="20000"></textarea></label><label>Genres séparés par des virgules<input bind:value={genres} /></label><label>Identifiants externes (JSON : tmdb, imdb…)<textarea bind:value={ids}></textarea></label><label>Âge minimum (vide : classification inconnue)<input type="number" min="0" max="21" bind:value={age} /></label><button>Enregistrer</button><button type="button" onclick={async()=>{if(await mutate(`/api/v1/admin/works/${work.id}/metadata`,'DELETE'))window.location.reload();}}>Revenir aux métadonnées du scan</button><label>Affiche PNG, JPEG ou WebP (2 Mio maximum)<input type="file" accept="image/png,image/jpeg,image/webp" onchange={upload} /></label><button type="button" onclick={async()=>{if(await mutate(`/api/v1/works/${work.id}/poster`,'DELETE'))window.location.reload();}}>Retirer l’affiche manuelle</button></fieldset></form>
{#if work.kind==='film'}<fieldset disabled={busy}><legend>Regrouper des copies</legend><label>Identifiant exact du même film sur un autre Node<input bind:value={copyId} /></label><button disabled={!copyId||copyId===work.id} onclick={async()=>{if(await mutate('/api/v1/admin/media-groups','POST',{workIds:[work.id,copyId],label:work.title}))window.location.reload();}}>Associer les deux films</button><button onclick={async()=>{if(await mutate(`/api/v1/admin/media-groups/${work.id}`,'DELETE'))window.location.reload();}}>Dissocier cette copie</button></fieldset>{/if}{/if}
{#if error}<p role="alert">{error}</p>{/if}{#if message}<p role="status">{message}</p>{/if}</details>
<style>details { margin:20px 0; } summary { cursor:pointer; } fieldset { display:grid;gap:12px;margin:16px 0;border:1px solid var(--color-line);border-radius:8px;padding:16px; } label { display:grid;gap:6px; } input,textarea,select,button { padding:10px;background:var(--color-surface);color:var(--color-text);border:1px solid var(--color-line);border-radius:6px;max-width:100%;box-sizing:border-box; } textarea { min-height:90px; } code { overflow-wrap:anywhere; } </style>
